package pl.rodzina.terminarz;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.*;
public class ReminderScheduler{
 static PendingIntent pending(Context c,String id,String title,long at){int n=id.hashCode()&0x7fffffff;Intent i=new Intent(c,ReminderReceiver.class);i.putExtra("title",title);i.putExtra("id",n);return PendingIntent.getBroadcast(c,n,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 public static void cancel(Context c,String id){AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent p=pending(c,id,"",0);a.cancel(p);p.cancel();}
 public static void schedule(Context c,String id,String title,long at){cancel(c,id);if(at<=System.currentTimeMillis())return;AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent p=pending(c,id,title,at);if(Build.VERSION.SDK_INT>=23)a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,p);else a.set(AlarmManager.RTC_WAKEUP,at,p);}
 public static void sync(Context c,String json){try{JSONArray arr=new JSONArray(json);Set<String> live=new HashSet<>();for(int x=0;x<arr.length();x++){JSONObject e=arr.getJSONObject(x);String id=e.optString("id");live.add(id);String rem=e.optString("reminder","");if(rem.isEmpty()) {cancel(c,id);continue;}String date=e.optString("date"),time=e.optString("time","");java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT);f.setLenient(false);java.util.Date d=f.parse(date+" "+(time.isEmpty()?"09:00":time));long at=d.getTime()-Long.parseLong(rem)*60000L;schedule(c,id,e.optString("what")+" · "+e.optString("person"),at);}
  android.content.SharedPreferences p=c.getSharedPreferences("reminder_state",0);Set<String> old=p.getStringSet("ids",new HashSet<>());for(String id:old)if(!live.contains(id))cancel(c,id);p.edit().putStringSet("ids",live).putString("json",json).apply();
 }catch(Exception ignored){}}
 public static void clear(Context c){android.content.SharedPreferences p=c.getSharedPreferences("reminder_state",0);for(String id:p.getStringSet("ids",new HashSet<>()))cancel(c,id);p.edit().clear().apply();}
}